style.css:
/* BLOODLINE - Discord */
:root {
  /* swap these colors if you want */
  --my-bg: #100607;
  --my-panel: #19090c;
  --my-panel-light: #260d12;
  --my-red: #c4142e;
  --my-red-bright: #ff2448;
  --my-text: #f5e8ea;
  --my-muted: #a78389;
}

/* main backgrounds */
body,
[class*="appMount"],
[class*="bg_"] {
  background: var(--my-bg) !important;
}

/* panels and sidebars */
[class*="sidebar_"],
[class*="panels_"],
[class*="container_"],
[class*="chat_"] {
  background-color: var(--my-panel) !important;
}

/* server list */
[class*="guilds_"] {
  background: #0c0507 !important;
}

/* selected and hovered elements */
[class*="selected_"],
[class*="modeSelected_"] {
  background: var(--my-panel-light) !important;
  border-radius: 9px !important;
}

[class*="clickable_"]:hover {
  background-color: #351017 !important;
  border-radius: 8px !important;
}

/* buttons */
button,
[class*="button_"] {
  border-radius: 8px !important;
}

/* links and mentions */
a,
[class*="mention"] {
  color: var(--my-red-bright) !important;
}

/* text */
[class*="title_"],
[class*="header_"] {
  color: var(--my-text) !important;
}

/* message hover */
[class*="message_"]:hover {
  background: #1c0a0e !important;
}

/* input boxes */
[class*="channelTextArea_"],
[class*="scrollableContainer_"] {
  background: #1b090d !important;
  border: 1px solid #47121d !important;
  border-radius: 12px !important;
}

/* subtle crimson glow */
[class*="selected_"] {
  box-shadow: inset 3px 0 var(--my-red-bright) !important;
}
